-- Report ID : RPT_119
-- Report    : Store Orders and Handbills
-- Module    : Price
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT      TRUNC(SYSDATE)                                       AS report_date,      woh.WF_ORDER_NO                                      AS store_order_no,     woh.ORDER_TYPE                                       AS order_type,     CASE woh.ORDER_TYPE         WHEN 'W' THEN 'Warehouse Replenishment'         WHEN 'S' THEN 'Supplier Direct'         WHEN 'T' THEN 'Transfer'         WHEN 'F' THEN 'Franchise Order'         ELSE woh.ORDER_TYPE     END                                                  AS order_type_desc,     woh.STATUS                                           AS order_status,     CASE woh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE woh.STATUS     END                                                  AS order_status_desc,     woh.CURRENCY_CODE                                    AS currency_code,     woh.APPROVAL_DATE                                    AS approval_date,     woh.COMMENTS                                         AS comments,     woh.CREATE_ID                                        AS created_by,      wod.CUSTOMER_LOC                                     AS store_id,     st.STORE_NAME                                        AS store_name,     st.STORE_TYPE                                        AS store_type,     CASE st.STORE_TYPE         WHEN 'C' THEN 'Company'         WHEN 'F' THEN 'Franchise'         ELSE st.STORE_TYPE     END                                                  AS store_type_desc,      so.DELIVERY_SLOT_ID                                  AS delivery_slot_id,     ds.DELIVERY_SLOT_DESC                                AS delivery_slot_desc,      wod.SOURCE_LOC_ID                                    AS source_loc_id,     wod.SOURCE_LOC_TYPE                                  AS source_loc_type,     CASE wod.SOURCE_LOC_TYPE         WHEN 'W' THEN wh.WH_NAME         WHEN 'S' THEN src_st.STORE_NAME     END                                                  AS source_loc_name,      wod.ITEM                                             AS item_id,     im.ITEM_DESC                                         AS item_description,     im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,     im.CLASS                                             AS class_no,     c.CLASS_NAME                                         AS class_name,     im.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                          AS subclass_name,     im.STANDARD_UOM                                      AS uom,      oh.SUPPLIER                                          AS supplier_id,     sp.SUP_NAME                                          AS supplier_name,      wod.REQUESTED_QTY                                    AS qty_ordered,     wod.NEED_DATE                                        AS need_date,     wod.NOT_AFTER_DATE                                   AS not_after_date,     woh.CREATE_DATETIME                                  AS order_date,     TRUNC(SYSDATE) - TRUNC(woh.CREATE_DATETIME)         AS days_since_order,      ril.REPL_METHOD                                      AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE ril.REPL_METHOD     END                                                  AS repl_method_desc,     ril.STOCK_CAT                                        AS stock_category,      wod.ACQUISITION_COST                                 AS acquisition_cost,     wod.CUSTOMER_COST                                    AS customer_cost,     ils.UNIT_COST                                        AS unit_cost,     il.UNIT_RETAIL                                       AS unit_retail,     ROUND(NVL(wod.REQUESTED_QTY, 0) * ils.UNIT_COST, 2) AS total_order_cost,     ROUND(NVL(wod.REQUESTED_QTY, 0) * il.UNIT_RETAIL, 2) AS total_order_retail,      th.TSF_NO                                            AS transfer_no,     th.STATUS                                            AS transfer_status,      ils.STOCK_ON_HAND                                    AS current_soh,     ils.AV_COST                                          AS weighted_avg_cost  FROM     MFCS_RDS.RDS_WV_WF_ORDER_HEAD           woh      JOIN  MFCS_RDS.RDS_WV_WF_ORDER_DETAIL   wod   ON  woh.WF_ORDER_NO     = wod.WF_ORDER_NO      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st   ON  wod.CUSTOMER_LOC    = st.STORE      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        im   ON  wod.ITEM             = im.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS               d    ON  im.DEPT              = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c    ON  im.DEPT              = c.DEPT                                                    AND im.CLASS             = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc   ON  im.DEPT              = sc.DEPT                                                    AND im.CLASS             = sc.CLASS                                                    AND im.SUBCLASS          = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC       il   ON  wod.ITEM             = il.ITEM                                                    AND wod.CUSTOMER_LOC    = il.LOC                                                    AND il.LOC_TYPE          = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH   ils  ON  wod.ITEM             = ils.ITEM                                                    AND wod.CUSTOMER_LOC    = ils.LOC                                                    AND ils.LOC_TYPE         = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC  ril  ON  wod.ITEM             = ril.ITEM                                                    AND wod.CUSTOMER_LOC    = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_STORE_ORDERS   so   ON  woh.WF_ORDER_NO      = so.WF_ORDER_NO                                                    AND wod.ITEM             = so.ITEM                                                    AND wod.CUSTOMER_LOC    = so.STORE      LEFT JOIN MFCS_RDS.RDS_WV_DELIVERY_SLOT  ds   ON  so.DELIVERY_SLOT_ID  = ds.DELIVERY_SLOT_ID      LEFT JOIN MFCS_RDS.RDS_WV_WH             wh   ON  wod.SOURCE_LOC_ID    = wh.WH                                                    AND wod.SOURCE_LOC_TYPE  = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_STORE          src_st ON wod.SOURCE_LOC_ID   = src_st.STORE                                                    AND wod.SOURCE_LOC_TYPE  = 'S'      LEFT JOIN MFCS_RDS.RDS_WV_TSFHEAD        th   ON  so.WF_ORDER_LINE_NO  = th.TSF_NO      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD         oh  ON  woh.WF_ORDER_NO      = oh.ORDER_NO     LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp  ON  oh.SUPPLIER          = sp.SUPPLIER  WHERE     woh.STATUS NOT IN ('C')     AND woh.CREATE_DATETIME >= ADD_MONTHS(SYSDATE, -3)     ORDER BY     st.STORE_NAME,     woh.CREATE_DATETIME DESC,     woh.WF_ORDER_NO,     im.ITEM_DESC